```c
#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int substituir = 0, consertar = 0;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);

        if (x < 50) {
            substituir++;
        } else if (x < 85) {
            consertar++;
        }
    }

    printf("%d %d\n", substituir, consertar);
    return 0;
}
```

